    (q : Fin L × Fin (k' + 1)) :
    ContDiff ℝ 1 fun p : (α ⊕ (Fin L × Fin k')) → ℝ => w (fun x => p (.inl x)) q

private theorem volume_measurePreserving_curry (ι κ : Type*) [Fintype ι] [Fintype κ] :
    MeasurePreserving (MeasurableEquiv.curry ι κ ℝ)
      (volume : Measure (ι × κ → ℝ)) (volume : Measure (ι → κ → ℝ))

private theorem volume_measurePreserving_uncurry (ι κ : Type*) [Fintype ι] [Fintype κ] :
    MeasurePreserving (MeasurableEquiv.curry ι κ ℝ).symm
      (volume : Measure (ι → κ → ℝ)) (volume : Measure (ι × κ → ℝ))

private theorem ancestors_notMem_parents (M : Model C dim 𝕜) (rank : C → ℕ)
    (hrank : ∀ c, ∀ p ∈ M.parents c, rank p < rank c) (c : C) :
    ∀ d ∈ M.ancestors (insert c (M.parents c)), c ∉ M.parents d

private theorem abs_sup'_sub_sup'_le {ι : Type*} {s : Finset ι} (hs : s.Nonempty)
    (f g : ι → ℝ) (r : ℝ) (h : ∀ i ∈ s, |f i - g i| ≤ r) :
    |s.sup' hs f - s.sup' hs g| ≤ r

private theorem measurableSet_floor_eq {ε : ℝ} (c : C) (a : Fin (dim c))
    (v : Assignment C dim) (n : ℤ) :
    MeasurableSet {M : Model C dim ℝ | ⌊M.cpt c a v / ε⌋ = n}

private theorem measurableSet_roundKey_eq {ε : ℝ}
    (k : (C → Finset C) × ((c : C) → Fin (dim c) → Assignment C dim → ℤ)) :
    MeasurableSet {M : Model C dim ℝ | M.roundKey ε = k}

private theorem sum_notLast {n : ℕ} (a : Fin n) (ha : (a : ℕ) + 1 = n) (x : Fin n → ℝ)
    (hsum : ∑ b, x b = 1) :
    ∑ b ∈ Finset.univ.filter (fun b : Fin n ↦ ¬ ((b : ℕ) + 1 = n)), x b = 1 - x a

private theorem bddAbove_measureRisk [Nonempty C] (sk : Skeleton C dim Bool ℝ)
    (modelClass : Set (Model C dim ℝ)) (n : ℕ)
    (strategy : RandomizedQueryStrategy sk) (estimator : MeasureEstimator C dim) :
    BddAbove {e : ℝ | ∃ M ∈ modelClass, ∃ family : PolicyFamily sk,
      AdmissibleFamily M sk 0 family ∧
        e = measureExpectedError sk M family strategy estimator n}

private theorem residualMultiplicity_of_balanced_even (p n h : ℕ)
    (hp : p ≤ n + h) (hn : n ≤ p + h) (hh : h ≤ p + n)
    (hpar : (p + n + h) % 2 = 0) : residualMultiplicity p n h = 1

private theorem residualMultiplicity_of_balanced_odd (p n h : ℕ)
    (hp : p ≤ n + h) (hn : n ≤ p + h) (hh : h ≤ p + n)
    (hpar : (p + n + h) % 2 = 1) : residualMultiplicity p n h = 2

private theorem fromCols_sub_fromCols {m n₁ n₂ : Type*} (A₁ B₁ : Matrix m n₁ ℝ)
    (A₂ B₂ : Matrix m n₂ ℝ) :
    Matrix.fromCols A₁ A₂ - Matrix.fromCols B₁ B₂ = Matrix.fromCols (A₁ - B₁) (A₂ - B₂)

private theorem fromRows_add_fromRows {m₁ m₂ n : Type*} (A₁ B₁ : Matrix m₁ n ℝ)
    (A₂ B₂ : Matrix m₂ n ℝ) :
    Matrix.fromRows A₁ A₂ + Matrix.fromRows B₁ B₂ = Matrix.fromRows (A₁ + B₁) (A₂ + B₂)

private theorem det_one_add_smul_conj {k : ℕ} {U : Matrix (Fin k) (Fin k) ℝ}
    (hU : U * star U = 1) (μ : Fin k → ℝ) (T : ℝ) :
    (1 + T • (U * Matrix.diagonal μ * star U)).det = ∏ i, (1 + T * μ i)

private theorem tendsto_half_nhdsGT :
    Tendsto (fun ε : ℝ => ε / 2) (nhdsWithin 0 (Ioi 0))
      (nhdsWithin 0 (Ioi 0))

private theorem exists_ker_of_rank_lt {K H : ℕ} (B : Matrix (Fin K) (Fin H) ℝ)
    (h : B.rank < H) :
    ∃ z : Fin H → ℝ, z ≠ 0 ∧ B *ᵥ z = 0

private theorem quadForm_smul {H : ℕ} (M : Matrix (Fin H) (Fin H) ℝ) (t : ℝ)
    (z : Fin H → ℝ) :
    (t • z) ⬝ᵥ (M *ᵥ (t • z)) = t ^ 2 * (z ⬝ᵥ (M *ᵥ z))

private theorem hasO7PairAt_of_volumeOrder {s lam : ℝ} {w : O7Space} {m : ℕ}
    (h : HasLocalVolumeOrder (centeredBandGerm (o7Loss s) w) w lam m) :
    HasO7PairAt s w lam m

