private theorem o31_cpt_child_congr {n : ℕ}
    {N : Model (Fin (n + 1)) (binaryDim (Fin (n + 1))) ℝ}
    (hp : N.parents = o31ChainParents) (i : Fin n) (a : Fin 2)
    (v w : Fin (n + 1) → Fin 2) (hvw : v i.succ = w i.succ) :
    N.cpt i.castSucc a v = N.cpt i.castSucc a w

private theorem o31_cpt_root_congr {n : ℕ}
    {N : Model (Fin (n + 1)) (binaryDim (Fin (n + 1))) ℝ}
    (hp : N.parents = o31ChainParents) (a : Fin 2) (v w : Fin (n + 1) → Fin 2) :
    N.cpt (Fin.last n) a v = N.cpt (Fin.last n) a w

private theorem o31_cpt_zero_eq {n : ℕ}
    {N : Model (Fin (n + 1)) (binaryDim (Fin (n + 1))) ℝ}
    (c : Fin (n + 1)) (v : Fin (n + 1) → Fin 2) : N.cpt c 0 v = 1 - N.cpt c 1 v

private theorem mul_left_cancel_of_mulVec_inj {n m : ℕ} {A : Matrix (Fin n) (Fin m) ℝ}
    (hA : Function.Injective A.mulVec) {X Y : Matrix (Fin m) (Fin m) ℝ}
    (h : A * X = A * Y) : X = Y

private theorem mul_permMatrix_diagonal_apply {n m : ℕ} (A : Matrix (Fin n) (Fin m) ℝ)
    (σ : Equiv.Perm (Fin m)) (d : Fin m → ℝ) (i : Fin n) (b : Fin m) :
    (A * σ.permMatrix ℝ * Matrix.diagonal d) i b = A i (σ.symm b) * d b

private theorem isKSparse_permScale {k m : ℕ} (π : Equiv.Perm (Fin m)) (μ : Fin m → ℝ)
    {v : Fin m → ℝ} (hv : IsKSparse k v) :
    IsKSparse k (fun a => μ (π.symm a) * v (π.symm a))

private theorem mulVec_eq_sum_of_support {n m : ℕ} (A : Matrix (Fin n) (Fin m) ℝ)
    (v : Fin m → ℝ) (S : Finset (Fin m)) (hv : ∀ j, j ∉ S → v j = 0) :
    A.mulVec v = ∑ j ∈ S, v j • A.col j

private theorem mul_permMatrix_diagonal_apply {n m : ℕ} (A : Matrix (Fin n) (Fin m) ℝ)
    (σ : Equiv.Perm (Fin m)) (d : Fin m → ℝ) (i : Fin n) (b : Fin m) :
    (A * σ.permMatrix ℝ * Matrix.diagonal d) i b = A i (σ.symm b) * d b

private theorem ncard_windows_containing_pair {m k : ℕ} [NeZero m] (hk1 : 1 ≤ k) (hkm : k < m)
    {p q : Fin m} (hpq : p ≠ q) :
    {t : Fin m | p ∈ cyclicWindow k t ∧ q ∈ cyclicWindow k t}.ncard < k

private theorem isSemialgebraic_companion_nonempty {lam : ℝ}
