    IsSemialgebraic {q : O34Index → ℝ |
      (separatedValues lam (o34ChartModel gr q).root).Nonempty}

private theorem isSemialgebraic_companion_singleton {lam : ℝ}
    (hlam0 : 0 < lam) (hlam2 : lam < 1 / 2) (gr : Orientation) (z : Fin 2) :
    IsSemialgebraic {q : O34Index → ℝ |
      separatedValues lam ((o34ChartModel gr q).child (other z))
        = {(o34ChartModel gr q).child z}}

private theorem isSemialgebraic_exactlyOneFlat
    {d : (O34Index → ℝ) → Fin 2 → ℝ}
    (hz : ∀ i, IsSemialgebraic {q : O34Index → ℝ | d q i = 0})
    (hn : ∀ i, IsSemialgebraic {q : O34Index → ℝ | d q i ≠ 0}) :
    IsSemialgebraic {q : O34Index → ℝ | ExactlyOneFlat (d q)}

private theorem assignedNeg_mul_v_eq_zero (I : Instance F) (R : RiskAssignment F B)
    {t : Fin 2} (h : negativeScore I R t = 0) (b : B) :
    assignedNeg I R t b * R.v b = 0

private theorem pointwise_zero (I : Instance F) (R : RiskAssignment F B)
    (hA : Calibrated I R) {t : Fin 2} (h : negativeScore I R t = 0) (σ : F) (b : B) :
    I.n t σ * I.p σ * (1 - I.p σ) * R.X σ b = 0

private theorem inf'_pair {α : Type w} [DecidableEq α] {a b : α} (f : α → ℝ)
    (h : ({a, b} : Finset α).Nonempty) :
    ({a, b} : Finset α).inf' h f = min (f a) (f b)

private theorem implication_trans {p q r : Bool}
    (hpq : boolImplies p q = true) (hqr : boolImplies q r = true) :
    boolImplies p r = true

private theorem preimage_eq_biUnion_fibres {α : Type v} [DecidableEq α]
    (X : U → α) [FiniteRange X] (s : Set α) :
    X ⁻¹' s = ⋃ a ∈ (rangeFinset X).filter (fun a => a ∈ s), X ⁻¹' {a}

private theorem sup'_pair {α : Type w} [DecidableEq α] {a b : α} (f : α → ℝ)
    (h : ({a, b} : Finset α).Nonempty) :
    ({a, b} : Finset α).sup' h f = max (f a) (f b)

private theorem fano_witness_identity {n : ℕ} (hn : 2 ≤ n) {p : ℝ} (hp0 : 0 ≤ p) :
    Real.negMulLog (1 - p) + ((n : ℝ) - 1) * Real.negMulLog (p / ((n : ℝ) - 1))
      = p * Real.log ((n : ℝ) - 1) + binEntropy p

private theorem fderiv_model (c d : X →L[ℝ] ℝ) :
    fderiv ℝ (fun y : X ↦ c y * c y - d y ^ 4)
      = fun x ↦ (2 * c x) • c - ((4 : ℝ) * d x ^ 3) • d

private theorem hasFDerivAt_model (c d : X →L[ℝ] ℝ) (x : X) :
    HasFDerivAt (fun y : X ↦ c y * c y - d y ^ 4)
      ((2 * c x) • c - ((4 : ℝ) * d x ^ 3) • d) x

private theorem fderiv_fderiv_sq_add (c d : X →L[ℝ] ℝ) (x : X) :
    fderiv ℝ (fderiv ℝ fun y : X ↦ c y * c y + d y * d y) x
      = ((2 : ℝ) • c).smulRight c + ((2 : ℝ) • d).smulRight d

private theorem fderiv_family (a b c q : X →L[ℝ] ℝ) :
    fderiv ℝ (fun y : X ↦ a y * a y + b y * b y - c y * c y + q y ^ 4)
      = fun x ↦ (2 * a x) • a + (2 * b x) • b - (2 * c x) • c + ((4 : ℝ) * q x ^ 3) • q

private theorem hasFDerivAt_family (a b c q : X →L[ℝ] ℝ) (x : X) :
    HasFDerivAt (fun y : X ↦ a y * a y + b y * b y - c y * c y + q y ^ 4)
      ((2 * a x) • a + (2 * b x) • b - (2 * c x) • c + ((4 : ℝ) * q x ^ 3) • q) x

private theorem volume_sublevel_sq {δ ε : ℝ} (hε : 0 < ε) (hδ : Real.sqrt ε < δ) :
    volume {x ∈ Metric.ball (0 : EuclideanSpace ℝ (Fin 1)) δ | x 0 ^ 2 ≤ ε}
      = ENNReal.ofReal (2 * Real.sqrt ε)

private theorem orderRule_unanimity
    {Alternative : Type} {voterCount : ℕ}
    [NeZero voterCount] [Fintype Alternative]
    {rule : SocialWelfareFunction Alternative voterCount}
    (hunanimity : Unanimity rule) :
    AISafetyAtlas.SocialChoice.Unanimity (orderRule rule)

lemma ite_and_one_zero (x y : Prop) {d : Decidable (x ∧ y)} :
    @ite _ (x ∧ y) d (1:ℝ) 0 =
      (@ite _ x (Classical.dec _) (1:ℝ) 0) * (@ite _ y (Classical.dec _) 1 0)

lemma cond_bind_le_second {f : Prob α} {g : α → Prob β} (p q : β → Prop) (i : α → Prop) {b : ℝ}
    (b0 : 0 ≤ b) (gb : ∀ x, f.prob x ≠ 0 → i x → (g x).cond p q ≤ b) :
    (f >>= λ x ↦ Prod.mk x <$> g x).cond (λ y ↦ p y.snd) (λ y ↦ q y.snd ∧ i y.fst) ≤ b

lemma pr_enrich_le_pr {f : Prob α} {g : α → Prob β} {p : α × β → Prop} {i : α → Prop}
    (pi : ∀ x y, f.prob x ≠ 0 → (g x).prob y ≠ 0 → p (x,y) → i x) :
    (f >>= λ x ↦ Prod.mk x <$> g x).pr p ≤ f.pr i

lemma pr_le_pr_enrich {f : Prob α} {g : α → Prob β} {p : α × β → Prop} {i : α → Prop}
    (ip : ∀ x y, f.prob x ≠ 0 → (g x).prob y ≠ 0 → i x → p (x,y)) :
    f.pr i ≤ (f >>= λ x ↦ Prod.mk x <$> g x).pr p
